SELECT 
FROM resume
WHERE id = #{id,typeHandler=com.resumecraft.common.UuidTypeHandler}
    AND user_id = #{owner,typeHandler=com.resumecraft.common.UuidTypeHandler}
    AND deleted = false

SELECT email
FROM users
WHERE id = #{owner,typeHandler=com.resumecraft.common.UuidTypeHandler}

SELECT EXISTS (
    SELECT 1
    FROM photo
    WHERE id = #{id,typeHandler=com.resumecraft.common.UuidTypeHandler}
        AND user_id = #{owner,typeHandler=com.resumecraft.common.UuidTypeHandler}
)

mapper.update:
UPDATE resume
SET title = #{title},
    updated_at = clock_timestamp()
WHERE id = #{id,typeHandler=com.resumecraft.common.UuidTypeHandler}
    AND user_id = #{owner,typeHandler=com.resumecraft.common.UuidTypeHandler}
    AND deleted = false

UPDATE resume
SET deleted = true,
    updated_at = clock_timestamp()
WHERE id = #{id,typeHandler=com.resumecraft.common.UuidTypeHandler}
    AND user_id = #{owner,typeHandler=com.resumecraft.common.UuidTypeHandler}
    AND deleted = false
